# Pulumi ComponentResource: Web App Infrastructure

## Project Structure

```
webapp-infra/
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── package.json
├── tsconfig.json
├── index.ts
└── lib/
    ├── web-app.ts      # ComponentResource
    └── config.ts
```

## Pulumi.yaml

```yaml
name: webapp-infra
runtime: nodejs
description: Stateless web app infra (bucket + RDS + IAM)
```

## Stack Config

### Pulumi.dev.yaml

```yaml
config:
  aws:region: us-east-1
  webapp-infra:environment: dev
  webapp-infra:dbInstanceClass: db.t3.micro
  webapp-infra:dbMultiAz: false
  webapp-infra:dbAllocatedStorage: "20"
  webapp-infra:dbPassword:
    secure: AQICAHg...  # Pulumi encrypted secret (ConfigSecret)
  webapp-infra:replicaRegion: ""   # no replication in dev
```

### Pulumi.prod.yaml

```yaml
config:
  aws:region: us-east-2
  webapp-infra:environment: prod
  webapp-infra:dbInstanceClass: db.t3.medium
  webapp-infra:dbMultiAz: true
  webapp-infra:dbAllocatedStorage: "50"
  webapp-infra:dbPassword:
    secure: AQICAHg...  # encrypted, never plaintext in Git
  webapp-infra:replicaRegion: us-west-2
```

## lib/config.ts

```typescript
import { Config } from "@pulumi/pulumi";

const cfg = new Config("webapp-infra");

export interface AppEnv {
    environment: "dev" | "prod";
    dbInstanceClass: string;
    dbMultiAz: boolean;
    dbAllocatedStorage: number;
    replicaRegion?: string; // bucket cross-region replication (prod only)
}

export const appConfig: AppEnv = {
    environment: cfg.require("environment") as "dev" | "prod",
    dbInstanceClass: cfg.get("dbInstanceClass") ?? "db.t3.micro",
    dbMultiAz: cfg.getBoolean("dbMultiAz") ?? false,
    dbAllocatedStorage: cfg.getNumber("dbAllocatedStorage") ?? 20,
    replicaRegion: cfg.get("replicaRegion") || undefined,
};

/** Secret — encrypted at rest by the Pulumi secrets provider, never plaintext. */
export const dbPassword = cfg.requireSecret("dbPassword");
```

## lib/web-app.ts

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { AppEnv } from "./config";

export interface WebAppArgs {
    environment: "dev" | "prod";
    dbInstanceClass: string;
    dbMultiAz: boolean;
    dbAllocatedStorage: number;
    dbPassword: pulumi.Output<string>;
    replicaRegion?: string;
}

export class WebApp extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly bucketPublicAccessBlock: aws.s3.BucketPublicAccessBlock;
    public readonly db: aws.rds.Instance;
    public readonly serviceRole: aws.iam.Role;
    public readonly connectionString: pulumi.Output<string>;

    constructor(name: string, args: WebAppArgs, opts?: pulumi.ComponentResourceOptions) {
        super("webapp:infra:WebApp", name, {}, opts);

        const isProd = args.environment === "prod";
        const tags = { Environment: args.environment, ManagedBy: "pulumi" };

        // --- S3 bucket: versioned, encrypted, no public access ---
        this.bucket = new aws.s3.BucketV2(`${name}-assets`, { tags }, { parent: this });

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: this.bucket.bucket,
            versioningConfiguration: { status: "Enabled" },
        }, { parent: this });

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-sse`, {
            bucket: this.bucket.bucket,
            rules: [{
                applyServerSideEncryptionByDefault: {
                    sseAlgorithm: "aws:kms",
                    kmsMasterKeyID: aws.kms.Key,
                } as any && undefined, // see note below — AES256 default, KMS in prod
                sseAlgorithm: isProd ? "aws:kms" : "AES256",
            }],
        }, { parent: this });

        this.bucketPublicAccessBlock = new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: this.bucket.bucket,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        // Cross-region replication (prod only)
        if (args.replicaRegion) {
            const replicaProvider = new aws.Provider(`${name}-replica-provider`, {
                region: args.replicaRegion,
            }, { parent: this });

            const replicaBucket = new aws.s3.BucketV2(`${name}-assets-replica`, {
                tags,
            }, { parent: this, provider: replicaProvider });

            new aws.s3.BucketVersioningV2(`${name}-assets-replica-versioning`, {
                bucket: replicaBucket.bucket,
                versioningConfiguration: { status: "Enabled" },
            }, { parent: this, provider: replicaProvider });

            const replicationRole = new aws.iam.Role(`${name}-replication-role`, {
                assumeRolePolicy: aws.iam.assumeRolePolicyForPrincipal({
                    Service: "s3.amazonaws.com",
                }),
            }, { parent: this });

            new aws.iam.RolePolicy(`${name}-replication-policy`, {
                role: replicationRole.name,
                policy: this.bucket.arn.apply(bucketArn =>
                    JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [{
                            Effect: "Allow",
                            Action: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
                            Resource: bucketArn,
                        }, {
                            Effect: "Allow",
                            Action: [
                                "s3:GetObjectVersionForReplication",
                                "s3:GetObjectVersionAcl",
                                "s3:GetObjectVersionTagging",
                            ],
                            Resource: pulumi.interpolate`${bucketArn}/*`,
                        }, {
                            Effect: "Allow",
                            Action: ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"],
                            Resource: pulumi.interpolate`${replicaBucket.arn}/*`,
                        }],
                    })),
            }, { parent: this });

            new aws.s3.BucketReplicationConfigV2(`${name}-assets-replication`, {
                bucket: this.bucket.bucket,
                role: replicationRole.arn,
                rules: [{
                    status: "Enabled",
                    destination: { bucket: replicaBucket.arn },
                    filter: {},
                }],
            }, { parent: this, dependsOn: [this.bucketPublicAccessBlock] });
        }

        // --- RDS PostgreSQL: protected, backed up, private ---
        const dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: aws.ec2.getSubnetsOutput({
                filters: [{ name: "default-for-az", values: ["true"] }],
            }).ids,
        }, { parent: this });

        const dbSecurityGroup = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            description: "RDS access",
            ingress: [{
                protocol: "tcp",
                fromPort: 5432,
                toPort: 5432,
                cidrBlocks: ["10.0.0.0/8"], // private network only
            }],
            egress: [{ protocol: "-1", fromPort: 0, toPort: 0, cidrBlocks: ["0.0.0.0/0"] }],
        }, { parent: this });

        this.db = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "16.3",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: args.dbAllocatedStorage,
            dbName: "webapp",
            username: "webapp_admin",
            password: args.dbPassword,
            dbSubnetGroupName: dbSubnetGroup.name,
            vpcSecurityGroupIds: [dbSecurityGroup.id],
            multiAz: args.dbMultiAz,
            storageEncrypted: isProd,
            deletionProtection: true,                    // acceptance: protection on
            backupRetentionPeriod: 7,                    // acceptance: >= 7 days
            publiclyAccessible: false,                   // acceptance: not public
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-db-final`,
            tags,
        }, { parent: this });

        this.connectionString = pulumi.interpolate`postgresql://webapp_admin:${args.dbPassword}@${this.db.endpoint}/webapp`;

        // --- IAM role for service accounts: least privilege, no wildcards on prod ---
        const assumePolicy = isProd
            ? pulumi.output(aws.eks.getCluster({ name: pulumi.interpolate`${name}-eks` }).clusterOidcIssuerUrl)
                .apply(o => JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{
                        Effect: "Allow",
                        Principal: { Federated: `arn:aws:iam::${aws.getCallerIdentityOutput().accountId}:oidc-provider/${o.replace("https://", "")}` },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: { [`${o.replace("https://", "")}:sub`]: `system:serviceaccount:webapp:webapp-sa` },
                        },
                    }],
                }))
            : JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: { Service: "ec2.amazonaws.com" }, // dev: programmatic use
                    Action: "sts:AssumeRole",
                }],
            });

        this.serviceRole = new aws.iam.Role(`${name}-service-role`, {
            assumeRolePolicy: assumePolicy,
            tags,
        }, { parent: this });

        new aws.iam.RolePolicy(`${name}-service-policy`, {
            role: this.serviceRole.name,
            // Least privilege — scoped to this stack's bucket; no wildcards in prod
            policy: pulumi.all([this.bucket.arn]).apply(([bucketArn]) => JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Action: ["s3:GetObject", "s3:PutObject"],
                    Resource: pulumi.interpolate`${bucketArn}/*`,
                }, {
                    Effect: "Allow",
                    Action: ["s3:ListBucket"],
                    Resource: bucketArn,
                }],
            })),
        }, { parent: this });

        this.registerOutputs({
            bucketName: this.bucket.bucket,
            dbEndpoint: this.db.endpoint,
            serviceRoleArn: this.serviceRole.arn,
        });
    }
}
```

## index.ts

```typescript
import * as pulumi from "@pulumi/pulumi";
import { WebApp } from "./lib/web-app";
import { appConfig, dbPassword } from "./lib/config";

const app = new WebApp("webapp", {
    environment: appConfig.environment,
    dbInstanceClass: appConfig.dbInstanceClass,
    dbMultiAz: appConfig.dbMultiAz,
    dbAllocatedStorage: appConfig.dbAllocatedStorage,
    dbPassword,
    replicaRegion: appConfig.replicaRegion,
});

export const bucketName = app.bucket.bucket;
export const dbEndpoint = app.db.endpoint;
export const serviceRoleArn = app.serviceRole.arn;
```

